    const positions = new Map(cells.map(([x, y], index) => [`${x},${y}`, index]));
    const frames = Array(cells.length).fill(null);
    frames[0] = { normal: [0, 0, 1], up: [0, 1, 0], right: [1, 0, 0] };
    const queue = [0];
